"""End-to-end probe with real tiny videos generated by ffmpeg (optional)."""

from __future__ import annotations

import shutil
import subprocess
from pathlib import Path

import pytest

from content_organizer.categories import Category
from content_organizer.planner import Options, build_plan
from content_organizer.probe import Orientation, ffprobe_version, find_ffprobe, probe

pytestmark = [
    pytest.mark.ffmpeg,
    pytest.mark.skipif(
        not (shutil.which("ffmpeg") and shutil.which("ffprobe")), reason="ffmpeg not on PATH"
    ),
]


def make_video(path: Path, size: str, rotate: int | None = None) -> Path:
    cmd = ["ffmpeg", "-v", "error", "-y"]
    if rotate is not None:
        cmd += ["-display_rotation", str(rotate)]
    cmd += ["-f", "lavfi", "-i", f"color=c=black:s={size}:d=0.2", "-pix_fmt", "yuv420p"]
    if rotate is not None:
        # re-wrap a raw encode so the display matrix is written to the container
        tmp = path.with_suffix(".src.mp4")
        subprocess.run([*cmd[:4], *cmd[6:], str(tmp)], check=True, timeout=60)
        subprocess.run(
            [
                "ffmpeg",
                "-v",
                "error",
                "-y",
                "-display_rotation",
                str(rotate),
                "-i",
                str(tmp),
                "-c",
                "copy",
                str(path),
            ],
            check=True,
            timeout=60,
        )
        tmp.unlink()
        return path
    subprocess.run([*cmd, str(path)], check=True, timeout=60)
    return path


def test_real_probe_orientation(tmp_path):
    ffprobe = find_ffprobe()
    assert ffprobe is not None and ffprobe_version(ffprobe)
    tall = make_video(tmp_path / "tall.mp4", "90x160")
    wide = make_video(tmp_path / "wide.mp4", "160x90")
    assert probe(tall, ffprobe).orientation is Orientation.VERTICAL
    assert probe(wide, ffprobe).orientation is Orientation.HORIZONTAL
    assert probe(tmp_path / "missing.mp4", ffprobe) is None


def test_real_rotated_video(tmp_path):
    ffprobe = find_ffprobe()
    rotated = make_video(tmp_path / "phone.mp4", "160x90", rotate=90)
    info = probe(rotated, ffprobe)
    assert info is not None
    assert info.rotation in (90, 270)
    assert info.orientation is Orientation.VERTICAL


def test_real_plan(tmp_path, config):
    src = tmp_path / "src"
    src.mkdir()
    make_video(src / "tall.mp4", "90x160")
    (src / "corrupt.mp4").write_bytes(b"not a video")
    plan = build_plan(src, tmp_path / "out", Options(date_folders=False), config=config)
    by_name = {m.src.name: m.category for m in plan.moves}
    assert by_name == {"tall.mp4": Category.VERTICAL, "corrupt.mp4": Category.VIDEOS}
